  <?php if ($sent) { ?><details><summary>Items already sent (<?php echo count($sent); ?>)</summary>
  <?php foreach ($sent as $x) { ?><div class="panel q-item">
    <h3><?php echo htmlspecialchars($x["program"] !== '' ? $x["program"] : $KIND[$x["kind"]], ENT_QUOTES, 'UTF-8'); ?> <span class="hint"><?php echo htmlspecialchars($KIND[$x["kind"]], ENT_QUOTES, 'UTF-8'); ?><?php if ($x["kind"] === 'proposal') { ?> · <?php echo htmlspecialchars($x["listing"], ENT_QUOTES, 'UTF-8'); ?><?php } ?></span></h3>
    <p class="hint"><?php echo htmlspecialchars(ny($x["when"]), ENT_QUOTES, 'UTF-8'); ?><?php if (isset($x["school"]) && $x["school"] !== '') { ?> · school: <?php echo htmlspecialchars($x["school"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if (isset($x["pickup"]) && $x["pickup"] !== '') { ?> · picks up: <?php echo htmlspecialchars($x["pickup"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if (isset($x["campType"]) && $x["campType"] !== '') { ?> · <?php echo htmlspecialchars($x["campType"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if (isset($x["sentBy"]) && $x["sentBy"] !== '') { ?> · sent by: <?php echo htmlspecialchars($x["sentBy"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if (isset($x["listing"]) && $x["listing"] !== '' && $x["kind"] !== 'proposal') { ?> · listing: <?php echo htmlspecialchars($x["listing"], ENT_QUOTES, 'UTF-8'); ?><?php } ?><?php if (!$open && isset($x["sent"])) { ?> · sent in batch <?php echo htmlspecialchars($x["sent"], ENT_QUOTES, 'UTF-8'); ?><?php if (!empty($x["rush"])) { ?> (rush)<?php } ?><?php } ?></p>
    <?php if ($x["website"] !== '') { ?><p>Website: <a href="<?php echo htmlspecialchars($x["website"], ENT_QUOTES, 'UTF-8'); ?>" rel="noopener nofollow" target="_blank"><?php echo htmlspecialchars($x["website"], ENT_QUOTES, 'UTF-8'); ?></a></p><?php } ?>
    <?php if ($x["details"] !== '') { ?><pre class="edit-ask"><?php echo htmlspecialchars($x["details"], ENT_QUOTES, 'UTF-8'); ?></pre><?php } ?>
    <form method="post" action="./" class="actions"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8'); ?>"><input type="hidden" name="id" value="<?php echo htmlspecialchars($x["id"], ENT_QUOTES, 'UTF-8'); ?>"><button class="btn" type="submit" name="do" value="drop">Done, take it off</button></form>
  </div><?php } ?>
  </details><?php } ?>
  <p><a class="btn" href="../">Back to editing</a> <a class="btn" href="../claims/">Claims and proposed changes</a></p>
</div>
